// Bridge API: list transactions of every account, since last_sync
const cfg = $json;
if (!cfg.bridge_user_uuid) return [{ json: { ...cfg, _skip: true, _txs: [] } }];
const auth = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.bridgeapi.io/v3/aggregation/authorization/token',
  headers: {
    'Client-Id': $env.BRIDGE_CLIENT_ID,
    'Client-Secret': $env.BRIDGE_CLIENT_SECRET,
    'Bridge-Version': '2025-01-15',
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({ user_uuid: cfg.bridge_user_uuid, external_user_id: cfg.user_id }),
  json: true,
});
const since = cfg.bridge_last_sync_at || new Date(Date.now() - 30 * 86400 * 1000).toISOString();
const txRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.bridgeapi.io/v3/aggregation/transactions?since=${encodeURIComponent(since)}&limit=200`,
  headers: {
    Authorization: `Bearer ${auth.access_token}`,
    'Client-Id': $env.BRIDGE_CLIENT_ID,
    'Client-Secret': $env.BRIDGE_CLIENT_SECRET,
    'Bridge-Version': '2025-01-15',
  },
  json: true,
});
return [{ json: { ...cfg, _txs: txRes.resources || [] } }];

const cfg = $json;
const out = [];
for (const t of (cfg._txs || [])) {
  out.push({ json: { ...cfg, _tx: t } });
}
if (out.length === 0) return [{ json: { ...cfg, _empty: true } }];
return out;

